/**
 * The 5 tabs the Detail screen's sections are grouped into. `DetailHeader` and the pill tab bar
 * are the only things `StockDetailRoute` keeps pinned -- `TechnicalRead` and the HIGH-urgency
 * alert scroll away with the rest of the content (see [DetailTabContent]'s leading block) so the
 * tab bar isn't permanently competing with them for screen space. `DirectNews` used to live in
 * `TIMELINE` alongside `ForwardCalls`/`EventLog`; it's its own tab now, sorted newest-first.
 */
enum class DetailTab(val labelRes: Int) {
    TECHNICALS(R.string.stock_detail_tab_technicals),
    FUNDAMENTALS(R.string.stock_detail_tab_fundamentals),
    THESIS(R.string.stock_detail_tab_thesis),
    TIMELINE(R.string.stock_detail_tab_timeline),
    NEWS(R.string.stock_detail_tab_news)
}

/**
 * The Detail screen's tab content -- everything below the pinned `DetailHeader` + tab bar (both
 * rendered by `StockDetailRoute`). Each tab is its own `LazyColumn` with its own `LazyListState`,
 * created once here and kept alive across tab switches (this composable itself never leaves
 * composition when `selectedTabIndex` changes -- only which branch of the `when` renders does),
 * so scrolling into a tab, switching away, and switching back lands right where that tab was left.
 *
 * `TechnicalRead` and the HIGH-urgency alert render as a leading block in *every* tab (handled
 * once, in [DetailTabContent], rather than duplicated in each of the 5 tab functions below) --
 * they're general context, not specific to any one tab.
 *
 * Section composables are unchanged -- only which tab calls them (and, for `DirectNews`, the sort
 * order of what's passed in) changed. The period chart (`PeriodChart` + `ChartRangePicker`) sits
 * in its original reserved position between SetupReasoning and HeadlineMetricsStrip, inside the
 * Technicals tab -- previously a `ChartPlaceholder` stand-in, now real data from `ChartsRepository`.
 */
@Composable
fun StockDetailScreen(
    detail: StockDetail?,
    preview: StockPreview?,
    selectedTabIndex: Int,
    expandedChipIds: Set<String>,
    expandedNewsIds: Set<String>,
    chartSeries: ChartSeries?,
    selectedChartRange: ChartRange,
    isChartLoading: Boolean,
    intradaySeries: IntradaySeries?,
    availableChartRanges: List<ChartRange>,
    onChartRangeSelected: (ChartRange) -> Unit,
    onToggleChip: (String) -> Unit,
    onToggleNews: (String) -> Unit,
    onArticleClick: (String) -> Unit,
    scaffoldPadding: PaddingValues,
    modifier: Modifier = Modifier
) {
    val paddingLarge = dimensionResource(id = R.dimen.padding_large)
    val sectionSpacing = dimensionResource(id = R.dimen.padding_xxlarge)
    val contentPadding = PaddingValues(
        // 💡 Was un-set (0dp) -- with TechnicalRead now the first scrollable item directly under
        // the tab bar instead of a fixed pinned block, that left it sitting flush against the
        // tabs with no breathing room at all.
        top = paddingLarge,
        bottom = scaffoldPadding.calculateBottomPadding() + paddingLarge,
        start = paddingLarge,
        end = paddingLarge
    )
    val lazyListStates = remember { List(DetailTab.entries.size) { LazyListState() } }

    Box(
        modifier = modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
    ) {
        when (DetailTab.entries[selectedTabIndex]) {
            DetailTab.TECHNICALS -> TechnicalsTabContent(
                detail = detail,
                preview = preview,
                chartSeries = chartSeries,
                selectedChartRange = selectedChartRange,
                isChartLoading = isChartLoading,
                intradaySeries = intradaySeries,
                availableChartRanges = availableChartRanges,
                onChartRangeSelected = onChartRangeSelected,
                lazyListState = lazyListStates[DetailTab.TECHNICALS.ordinal],
                contentPadding = contentPadding,
                sectionSpacing = sectionSpacing
            )

            DetailTab.FUNDAMENTALS -> FundamentalsTabContent(
                detail = detail,
                lazyListState = lazyListStates[DetailTab.FUNDAMENTALS.ordinal],
                contentPadding = contentPadding,
                sectionSpacing = sectionSpacing
            )

            DetailTab.THESIS -> ThesisTabContent(
                detail = detail,
                preview = preview,
                expandedChipIds = expandedChipIds,
                onToggleChip = onToggleChip,
                lazyListState = lazyListStates[DetailTab.THESIS.ordinal],
                contentPadding = contentPadding,
                sectionSpacing = sectionSpacing
            )

            DetailTab.TIMELINE -> TimelineTabContent(
                detail = detail,
                lazyListState = lazyListStates[DetailTab.TIMELINE.ordinal],
                contentPadding = contentPadding,
                sectionSpacing = sectionSpacing
            )

            DetailTab.NEWS -> NewsTabContent(
                detail = detail,
                expandedNewsIds = expandedNewsIds,
                onToggleNews = onToggleNews,
                onArticleClick = onArticleClick,
                lazyListState = lazyListStates[DetailTab.NEWS.ordinal],
                contentPadding = contentPadding,
                sectionSpacing = sectionSpacing
            )
        }
    }
}

@Composable
private fun TechnicalsTabContent(
    detail: StockDetail?,
    preview: StockPreview?,
    chartSeries: ChartSeries?,
    selectedChartRange: ChartRange,
    isChartLoading: Boolean,
    intradaySeries: IntradaySeries?,
    availableChartRanges: List<ChartRange>,
    onChartRangeSelected: (ChartRange) -> Unit,
    lazyListState: LazyListState,
    contentPadding: PaddingValues,
    sectionSpacing: Dp
) {
    val setupConfirming = detail?.setupConfirming.orEmpty()
    val setupConflicting = detail?.setupConflicting.orEmpty()
    val hasSetupReasoning = setupConfirming.isNotEmpty() || setupConflicting.isNotEmpty()
    val hasHeadlineMetrics = detail?.technicalIndicators != null
    val hasKeyLevels = detail?.levels != null
    val hasWatchList = !detail?.watchList.isNullOrEmpty()
    val hasTabContent = hasSetupReasoning || hasHeadlineMetrics || hasKeyLevels || hasWatchList

    DetailTabContent(detail, hasTabContent, lazyListState, contentPadding, sectionSpacing) {
        if (hasSetupReasoning) {
            item {
                SetupReasoning(
                    technicalSetup = preview?.technicalSetup,
                    setupConfidence = preview?.setupConfidence,
                    setupNetBias = preview?.setupNetBias,
                    setupConfirming = setupConfirming,
                    setupConflicting = setupConflicting
                )
            }
        }

        // Period chart (5D/1M/6M/YTD/1Y), between SetupReasoning and HeadlineMetricsStrip, matching
        // the Design mockup's layout -- previously reserved-but-empty space (`ChartPlaceholder`),
        // now real data from `ChartsRepository`. `PeriodChart` itself handles the loading/empty
        // states at a fixed height (see its own doc comment) -- switching ranges used to swap this
        // out for a shorter empty-state block and back, visibly shifting everything below it.
        item {
            Column {
                if (selectedChartRange == ChartRange.ONE_DAY) {
                    IntradayPeriodChart(
                        points = intradaySeries?.points.orEmpty(),
                        previousClose = intradaySeries?.previousClose,
                        date = intradaySeries?.date,
                        isLoading = isChartLoading,
                        modifier = Modifier.fillMaxWidth()
                    )
                } else {
                    // currentPrice keeps a still-open trading day's chart endpoint from lagging
                    // behind the live price shown elsewhere on this page (see PeriodChart's own
                    // doc comment) -- preview.price is that same live-priced field.
                    PeriodChart(
                        points = chartSeries?.points.orEmpty(),
                        isLoading = isChartLoading,
                        currentPrice = preview?.price,
                        modifier = Modifier.fillMaxWidth()
                    )
                }
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                ChartRangePicker(
                    selectedRange = selectedChartRange,
                    onRangeSelected = onChartRangeSelected,
                    availableRanges = availableChartRanges
                )
            }
        }

        if (hasHeadlineMetrics) {
            item { HeadlineMetricsStrip(indicators = detail?.technicalIndicators) }
            item { MomentumAndTrend(indicators = detail?.technicalIndicators) }
        }
        if (detail?.technicalIndicators?.returns != null) {
            item { Returns(returns = detail.technicalIndicators.returns) }
        }
        if (hasKeyLevels) {
            item { KeyLevels(levels = detail?.levels, price = preview?.price) }
        }
        if (hasWatchList) {
            item { WatchList(items = detail?.watchList) }
        }
    }
}

